1	// Glues CsrTrigger and StateDrain. The simulator's run-loop calls on_retire
2	// once per committed PC; the controller decides via the trigger map whether
3	// to drain state and returns the populated hybrid_state_v1 if so. The
4	// caller (simulator.hpp) is responsible for writing the file and exiting
5	// with EXIT_HANDOFF_TO_QEMU.
6	
7	#pragma once
8	
9	#include "hybrid/csr_trigger.hpp"
10	#include "hybrid/insn_match.h"
11	#include "hybrid/measure_start_snapshot.hpp"
12	#include "hybrid/resume_driver.hpp"
13	#include "hybrid/state_abi.h"
14	#include "hybrid/state_drain.hpp"
15	
16	#include <cstdint>
17	#include <optional>
18	#include <utility>
19	
20	namespace hybrid
21	{
22	
23	template<typename Trigger, typename Observer = NullObserver>
24	class HandoffController
25	{
26	public:
27	  HandoffController(Trigger trigger, DmiBus& bus)
28	      : trigger_{std::move(trigger)}, drain_{bus}
29	  {}
30	
31	  HandoffController(Trigger trigger, DmiBus& bus, Observer observer)
32	      : trigger_{std::move(trigger)},
33	        drain_{bus},
34	        observer_{std::move(observer)}
35	  {}
36	
37	  // Snapshot of the QEMU 1 input state. When set, drain merges FP/CSR/V
38	  // fields from the snapshot into the freshly drained GPRs+PC, avoiding
39	  // a per-field DM Abstract Command on every handoff.
40	  void set_passthrough_input(hybrid_state_v1 input)
41	  {
42	    passthrough_ = input;
43	  }
44	
45	  // Read-only view of the underlying trigger. Used by the ROI kanata-gate
46	  // derivation, which needs to read scanned EXIT PCs without consuming them.
47	  auto trigger() const -> const Trigger& { return trigger_; }
48	
49	  // Read-only view of the observer slot. F16 (StateDrain) reads the warmup
50	  // snapshot from here when copying into the ABI struct.
51	  auto observer() const -> const Observer& { return observer_; }
52	  auto observer() -> Observer& { return observer_; }
53	
54	  template<typename GprProbe>
55	  auto on_retire(uint64_t pc, GprProbe&& read_gpr)
56	    -> std::optional<hybrid_state_v1>
57	  {
58	    if constexpr (requires { trigger_.observe_commit(); }) {
59	      trigger_.observe_commit();
60	    }
61	    if constexpr (requires { observer_.observe_commit(); }) {
62	      observer_.observe_commit();
63	    }
64	    const auto hit = trigger_.lookup(pc);
65	    if (!hit) return std::nullopt;
66	
67	    bool fire = false;
68	    switch (hit->kind) {
69	    case HYBRID_HANDOFF_EXIT:
70	      fire = true;
71	      break;
72	    case HYBRID_HANDOFF_RUNTIME: {
73	      const auto rs1 = decode_csrrw_rs1(hit->insn);
74	      fire = (read_gpr(rs1) == 1u);
75	      break;
76	    }
77	    case HYBRID_HANDOFF_ENTER:  // entry is QEMU's job; vsim ignores it
78	    case HYBRID_HANDOFF_NONE:
79	      break;
80	    }
81	    if (!fire) return std::nullopt;
82	    // F16: push warmup snapshot into the drain right before it runs so the
83	    // returned state file carries mcycle_at_measure_start / minstret_at_measure_start.
84	    // The if-constexpr branch compiles away for NullObserver (no accessors).
85	    if constexpr (requires { observer_.mcycle_at_measure_start(); }) {
86	      drain_.set_warmup_snapshot(observer_.mcycle_at_measure_start(),
87	                                 observer_.minstret_at_measure_start());
88	    }
89	    if (passthrough_) return drain_.drain_with_passthrough(*passthrough_);
90	    return drain_.drain();
91	  }
92	
93	private:
94	  Trigger trigger_;
95	  StateDrain drain_;
96	  Observer observer_{};
97	  std::optional<hybrid_state_v1> passthrough_;
98	};
