27	TEST_CASE("HandoffController: EXIT csrwi triggers drain and returns state")
28	{
29	  RecordingBus bus;
30	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
31	  bus.regfile[hybrid::regno_gpr(12)] = 3;
32	  bus.regfile[hybrid::regno_csr(RD::kCsrDpc)] = 0x80000004;
33	
34	  hybrid::CsrTrigger trigger;
35	  const std::array<uint32_t, 1> code{encode_csrrwi(0, 0x7C0, 1)};
36	  trigger.scan_buffer(as_bytes(code), /*base_pc=*/0x80000000);
37	
38	  hybrid::HandoffController h(std::move(trigger), bus);
39	  const auto state = h.on_retire(0x80000000, [](uint8_t) { return 0u; });
40	
41	  REQUIRE(state);
42	  CHECK(state->magic == HYBRID_STATE_MAGIC);
43	  CHECK(state->gpr[12] == 3);
