26	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
27	
28	  hybrid::StateDrain drain(bus);
29	  (void) drain.drain();
30	
31	  REQUIRE(bus.ops.size() >= 2);
32	  CHECK(bus.ops[0].kind == DmiOp::Kind::Write);
33	  CHECK(bus.ops[0].reg == RD::kDmcontrol);
34	  CHECK((bus.ops[0].value & RD::kDmcontrolDmactive) != 0u);
35	  CHECK((bus.ops[0].value & RD::kDmcontrolHaltreq) == 0u);
