37	  CHECK(bus.ops[1].kind == DmiOp::Kind::Write);
38	  CHECK(bus.ops[1].reg == RD::kDmcontrol);
39	  CHECK((bus.ops[1].value & RD::kDmcontrolDmactive) != 0u);
