103	TEST_CASE("drain() does NOT issue Abstract Commands for FPRs/CSRs/PMPs - those "
104	          "fields are zero in the bare drain output and merged in by "
105	          "drain_with_passthrough")
106	{
107	  RecordingBus bus;
108	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
109	  for (uint16_t i = 0; i < 32; ++i)
110	    bus.regfile[hybrid::regno_fpr(i)] = 0xf000000000000000ULL + i;
111	
112	  hybrid::StateDrain drain(bus);
113	  const auto state = drain.drain();
114	
115	  for (int i = 0; i < 32; ++i) CHECK(state.fpr[i] == 0u);
116	  CHECK(state.mstatus == 0u);
117	  CHECK(state.satp    == 0u);
118	  CHECK(state.vlenb   == 0u);
119	}
