121	TEST_CASE("drain_with_passthrough copies CSR/PMP/V-payload slots from input and "
122	          "freshly drains GPRs/PC from the DM")
123	{
124	  RecordingBus bus;
125	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
126	  bus.regfile[hybrid::regno_csr(RD::kCsrDpc)] = 0x80001234ULL;
127	  for (uint16_t i = 0; i < 32; ++i)
128	    bus.regfile[hybrid::regno_gpr(i)] = 0x10000000ULL + i;
129	
130	  hybrid_state_v1 input{};
131	  input.magic   = HYBRID_STATE_MAGIC;
132	  input.version = HYBRID_STATE_VERSION;
133	  input.flags   = HYBRID_FLAG_RV64;
134	  input.priv    = 3;
135	  input.mstatus = 0x1800ULL;
136	  input.satp    = 0x8000000080000000ULL;
137	  for (int i = 0; i < HYBRID_PMP_CFG_NUM; ++i)  input.pmpcfg[i]  = 0xa0 + i;
138	  for (int i = 0; i < HYBRID_PMP_ADDR_NUM; ++i) input.pmpaddr[i] = 0xb0 + i;
139	  input.vlenb = 64;
140	  for (std::size_t i = 0; i < sizeof(input.vreg); ++i) input.vreg[i] = i & 0xff;
141	
142	  hybrid::StateDrain drain(bus);
143	  const auto state = drain.drain_with_passthrough(input);
144	
145	  CHECK(state.mstatus == 0x1800ULL);
146	  CHECK(state.satp    == 0x8000000080000000ULL);
147	  CHECK(state.pmpcfg[5]  == uint64_t(0xa5));
148	  CHECK(state.pmpaddr[7] == uint64_t(0xb7));
149	  CHECK(state.vlenb == 64ULL);
150	  CHECK(state.vreg[100] == uint8_t(100));
151	
152	  // GPRs/PC come from the DM read, not the input.
153	  for (int i = 1; i < 32; ++i)
154	    CHECK(state.gpr[i] == 0x10000000ULL + uint64_t(i));
155	  CHECK(state.pc == 0x80001234ULL);
156	}
